#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}


# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────
#
# Deploy the principals' web app (PRD E12-S7). Decided 2026-11-16: a new Supabase organization and project for Valley Capital;
# hosting on the existing Vercel project "web" in the cartboost team, with previews protected; the worker in GitHub Actions.
# Run from anywhere: bash scripts/deploy-wizard.sh. Needs node (for the smoke test) and, for the GitHub stage, an authenticated gh.
# It writes only the PUBLIC values (project URL, publishable/anon key) to web/.env.local, which git ignores. Secret keys are typed
# hidden and go only to GitHub Actions secrets; they are never written to a file.

cd "$(dirname "$0")/.."
ENV_FILE="web/.env.local"
TOTAL_STAGES=12
VERCEL_PROJECT="https://vercel.com/cartboost/web"

banner "Deploy the Valley Capital outbound web app"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Supabase: a new organization and project"
say "The database lives in its own organization, used only for Valley Capital (PRD Q17)."
open_url "https://supabase.com/dashboard/organizations"
step "Click 'New organization'. Name it for Valley Capital. Choose the plan."
step "In that organization, click 'New project'. Name it (e.g. valley-outbound), set a strong database password, pick a US region."
step "Wait until the project finishes setting up."
step "Open Project Settings → Data API (or API) and copy the Project URL (https://<ref>.supabase.co)."
ask SUPABASE_URL "Paste the Project URL:"
SUPABASE_URL="${SUPABASE_URL%/}"
[[ "$SUPABASE_URL" =~ ^https://[a-z0-9]+\.supabase\.co$ ]] || warn "That does not look like https://<ref>.supabase.co; check it before going on."
write_env SUPABASE_URL "$SUPABASE_URL"
REF="${SUPABASE_URL#https://}"; REF="${REF%%.*}"
note "Project ref: $REF"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Supabase: the two keys"
open_url "https://supabase.com/dashboard/project/$REF/settings/api-keys"
say "Two keys. The PUBLIC one goes in the web app. The SECRET one is only for the worker, and never in the web app."
step "Copy the publishable key (sb_publishable_…) or, on the legacy tab, the anon key."
ask SUPABASE_ANON_KEY "Paste the publishable (anon) key:"
case "$SUPABASE_ANON_KEY" in sb_secret_*) warn "That is a SECRET key. The web app refuses it. Paste the publishable key instead."; ask SUPABASE_ANON_KEY "Publishable (anon) key:";; esac
write_env SUPABASE_ANON_KEY "$SUPABASE_ANON_KEY"
step "Now copy a secret key (sb_secret_…) or, on the legacy tab, the service_role key. Input is hidden."
ask_secret SUPABASE_SERVICE_ROLE_KEY "Paste the secret (service role) key:"
note "Kept in memory for stages 11 and 12 only; it is not written to any file."

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Supabase: create the tables (9 migrations, in order)"
open_url "https://supabase.com/dashboard/project/$REF/sql/new"
say "Paste each file below into the SQL editor, run it, and check it says 'Success' before the next."
for f in supabase/migrations/*.sql; do step "$f"; done
note "Or, with the Supabase CLI: supabase link --project-ref $REF && supabase db push"
pause "All 9 run without errors? Press Enter."

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Vercel: the app's address"
open_url "$VERCEL_PROJECT"
step "On the project page, copy the production domain (the address under 'Domains')."
ask APP_URL "Paste the app's address (https://…):"
APP_URL="${APP_URL%/}"
[[ "$APP_URL" =~ ^https:// ]] || APP_URL="https://$APP_URL"
note "App: $APP_URL"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Supabase: sign-in settings"
open_url "https://supabase.com/dashboard/project/$REF/auth/providers"
step "Authentication → Sign In / Providers: turn OFF 'Allow new users to sign up'. Save."
open_url "https://supabase.com/dashboard/project/$REF/auth/url-configuration"
step "Authentication → URL Configuration: set Site URL to $APP_URL"
step "Add this Redirect URL: $APP_URL/auth/callback . Save."
pause "Done? Press Enter."

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Supabase: the principals"
say "Type each principal's name and email. Leave the name empty to finish."
SQL="insert into public.principals (email, name, active) values"
SEP=""; COUNT=0
while true; do
  P_NAME=""; P_EMAIL=""
  printf '  %sName:%s ' "$BOLD" "$RESET"; read -r P_NAME || true
  [[ -z "$P_NAME" ]] && break
  printf '  %sEmail:%s ' "$BOLD" "$RESET"; read -r P_EMAIL || true
  P_EMAIL=$(printf '%s' "$P_EMAIL" | tr '[:upper:]' '[:lower:]' | tr -d '[:space:]')
  [[ "$P_EMAIL" == *@*.* ]] || { warn "That email looks wrong; skipped."; continue; }
  SQL="$SQL$SEP ('${P_EMAIL//\'/\'\'}', '${P_NAME//\'/\'\'}', true)"; SEP=","; COUNT=$((COUNT + 1))
done
if (( COUNT )); then
  SQL="$SQL on conflict (email) do update set name = excluded.name, active = true;"
  open_url "https://supabase.com/dashboard/project/$REF/sql/new"
  step "Run this in the SQL editor:"
  printf '\n%s\n\n' "$SQL"
  open_url "https://supabase.com/dashboard/project/$REF/auth/users"
  step "Authentication → Users → 'Invite user': invite each of the $COUNT email(s) above."
  pause "Rows added and invites sent? Press Enter."
else
  warn "No principals added. Nobody can sign in until rows exist in public.principals."
  SKIPPED+=("Add principals: rows in public.principals, and an invite for each")
fi

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Smoke test (public key only)"
say "Checks that sign-ups are off and every table and function exists and refuses the public key."
if command -v node >/dev/null 2>&1 && [[ -d node_modules ]]; then
  if SUPABASE_URL="$SUPABASE_URL" SUPABASE_ANON_KEY="$SUPABASE_ANON_KEY" node cli.mjs platform smoke; then
    printf '  %s✓ smoke test passed%s\n' "$GREEN" "$RESET"
  else
    warn "The smoke test failed. Read its message, fix that stage, and run this wizard again."
    SKIPPED+=("A passing smoke test: node cli.mjs platform smoke")
  fi
else
  warn "node or node_modules missing (run npm install). Skipping the smoke test."
  SKIPPED+=("Smoke test: npm install, then SUPABASE_URL=… SUPABASE_ANON_KEY=… node cli.mjs platform smoke")
fi
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Vercel: settings for the web project"
open_url "$VERCEL_PROJECT/settings"
step "Build and Deployment: Root Directory = web ; turn ON 'Include files outside the root directory in the Build Step'."
step "Environment Variables (Production and Preview):"
note "    SUPABASE_URL      = $SUPABASE_URL"
note "    SUPABASE_ANON_KEY = the publishable key from stage 2 (in $ENV_FILE)"
warn "Never add the secret (service role) key here. The app refuses to start with one."
step "Git: production branch = main."
step "Deployment Protection: turn ON Vercel Authentication (Standard Protection), so previews need a Vercel login."
pause "All four set? Press Enter."

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Vercel: the duplicate projects (optional)"
say "This repository also deploys to web-rr7x and valley-capital-partner-outbound on cartboost, each making public previews."
if confirm "Disconnect both from this repository now?"; then
  for p in web-rr7x valley-capital-partner-outbound; do
    open_url "https://vercel.com/cartboost/$p/settings/git"
    step "$p: Settings → Git → 'Disconnect' the repository (or delete the project under Settings → General)."
  done
  pause "Both disconnected? Press Enter."
else
  SKIPPED+=("Disconnect the duplicate Vercel projects web-rr7x and valley-capital-partner-outbound")
fi

# ── 10 ────────────────────────────────────────────────────────────────────
stage "First deploy: check a page loads data"
open_url "$VERCEL_PROJECT/deployments"
step "Redeploy the latest production deployment (… menu → Redeploy), so the new settings apply."
step "Open $APP_URL, sign in with a principal's email link, and open Status."
say "This is the first run on Vercel of the engine loaded at runtime. If a page errors, check the deployment's logs:"
note "    'Cannot find module' means 'Include files outside the root directory' is off."
note "    'The app is not configured' means the two variables are missing."
if ! confirm "Did Status load after signing in?"; then
  SKIPPED+=("A page loading data on Vercel (stage 10): check the deployment logs")
fi

# ── 11 ────────────────────────────────────────────────────────────────────
stage "GitHub Actions: the worker's secrets"
say "The scheduled worker (.github/workflows/platform-worker.yml) uses the secret key; the web app never does."
set_secret SUPABASE_URL "$SUPABASE_URL"
set_secret SUPABASE_SERVICE_ROLE_KEY "$SUPABASE_SERVICE_ROLE_KEY"
open_url "https://console.anthropic.com/settings/keys"
step "Create (or copy) an Anthropic API key for the worker: research and drafting use it. Input is hidden."
ask_secret ANTHROPIC_API_KEY "Paste the Anthropic API key (Enter to skip for now):"
if [[ -n "$ANTHROPIC_API_KEY" ]]; then set_secret ANTHROPIC_API_KEY "$ANTHROPIC_API_KEY"; else SKIPPED+=("GitHub secret ANTHROPIC_API_KEY (research and drafting jobs need it)"); fi
if confirm "Turn the scheduled worker on now (PLATFORM_ENABLED=true)?"; then set_var PLATFORM_ENABLED true; else SKIPPED+=("GitHub variable PLATFORM_ENABLED=true, when you want the worker to run"); fi

# ── 12 ────────────────────────────────────────────────────────────────────
stage "Load existing data (optional)"
say "Copies a local data folder (OUTBOUND_DATA_DIR) into the platform. Safe to re-run."
if confirm "Push a data folder now?"; then
  ask PUSH_DIR "Data folder path:"
  if [[ -d "$PUSH_DIR" ]] && SUPABASE_URL="$SUPABASE_URL" SUPABASE_SERVICE_ROLE_KEY="$SUPABASE_SERVICE_ROLE_KEY" node cli.mjs platform push --from "$PUSH_DIR"; then
    printf '  %s✓ pushed%s\n' "$GREEN" "$RESET"
  else
    warn "The push did not finish. Fix the message above and re-run: node cli.mjs platform push --from DIR"
    SKIPPED+=("Data push: SUPABASE_URL=… SUPABASE_SERVICE_ROLE_KEY=… node cli.mjs platform push --from DIR")
  fi
fi
pause

finish
